import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;\s*$')
    token_re = re.compile(r'\s*(\d+|[A-Za-z_]\w*|[()+\-*%])')

    def evaluate(expr):
        expr = re.sub(r'\bmod\b', '%', expr)
        pos = 0
        tokens = []
        while pos < len(expr):
            if expr[pos].isspace():
                pos += 1
                continue
            m = token_re.match(expr, pos)
            if not m:
                raise ValueError("bad expression")
            tokens.append(m.group(1))
            pos = m.end()
        out = []
        for t in tokens:
            if re.fullmatch(r'[A-Za-z_]\w*', t):
                out.append(str(env.get(t, 0)))
            else:
                out.append(t)
        return eval(' '.join(out), {"__builtins__": {}}, {})

    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith('//'):
            continue
        if '//' in s:
            s = s.split('//', 1)[0].strip()
        m = assign_re.match(s)
        if not m:
            continue
        var, expr = m.group(1), m.group(2)
        try:
            env[var] = evaluate(expr)
        except Exception:
            continue

    a = env.get('a', 0)
    b = env.get('b', 0)
    t = env.get('TMP', 0)
    print(f"a ?= {a}; b ?= {b}; TMP ?= {t};")

main()
